package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.attributes.Attributes;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Node_hasAttr_TriageGen0Test {

    private Node node;

    @Before
    public void setUp() {
        Attributes attributes = new Attributes();
        node = new Node("http://example.com", attributes) {
            @Override
            public String nodeName() {
                return "test";
            }
        };
    }

    @Test
    public void testHasAttr_WithValidAttributeKey() {
        node.attr("class", "test-class");
        assertTrue(node.hasAttr("class"));
    }

    @Test
    public void testHasAttr_WithInvalidAttributeKey() {
        assertFalse(node.hasAttr("nonexistent"));
    }

    @Test
    public void testHasAttr_WithNullAttributeKey_ShouldThrowException() {
        Exception exception = null;
        try {
            node.hasAttr(null);
        } catch (IllegalArgumentException e) {
            exception = e;
        }
        assertNotNull(exception);
    }

    @Test
    public void testHasAttr_WithEmptyAttributeKey() {
        assertFalse(node.hasAttr(""));
    }

    @Test
    public void testHasAttr_WithWhitespaceAttributeKey() {
        assertFalse(node.hasAttr("   "));
    }

    @Test
    public void testHasAttr_AfterRemovingAttribute() {
        node.attr("id", "test-id");
        assertTrue(node.hasAttr("id"));
        node.removeAttr("id");
        assertFalse(node.hasAttr("id"));
    }

    @Test
    public void testHasAttr_WithMultipleAttributes() {
        node.attr("class", "test-class");
        node.attr("id", "test-id");
        assertTrue(node.hasAttr("class"));
        assertTrue(node.hasAttr("id"));
    }

    @Test
    public void testHasAttr_WithDuplicateAttributes() {
        node.attr("class", "test-class");
        node.attr("class", "new-class");
        assertTrue(node.hasAttr("class"));
    }
}
